from npcs import *

# ---------------- Ashbrook ----------------
npc("orwyn", "Elder Orwyn", "ashbrook", "mentor", "sage", 0, 1, (200, 200, 205), (96, 84, 120), (70, 60, 90), (80, 60, 40), "Gruff and gentle: a retired sage who hides his worry behind chores.", (4, 16),
    ["Chores before the ceremony, {player_name}. The crystal judges the heart, not the hour you wake. Fetch the water, then we walk to the shrine together.",
     "I am only an echo now, boy. Walk on. You are carrying more than you think.",
     "You are carrying it better than I did. Keep your friends close.",
     "The Crown is light again. I always said you would outgrow my sword."],
    [("orwyn", "Your grandfather was never a hero, you know. Just the man who stayed put when it mattered."), ("orwyn", "Heroes leave. Elders stay and mend the roof. Both are needed."),
     ("orwyn", "If the crystal glows, it will frighten them. Let them be frightened. Fear fades faster than shame.")], stage="ash", required=True, visible=["quest.MQ03 != complete"], skin=0)
npc("tilly", "Tilly Brooke", "ashbrook", "friend", "villager", 1, 2, (150, 96, 60), (180, 120, 90), (110, 80, 70), (80, 60, 50), "Quick-witted, loyal, and the only one who never treated {player_name} like a weapon.", (-4, 18),
    ["There you are! You missed breakfast and half the chores. Don't think the ceremony gets you out of mucking the stable.",
     "I'm running the refugee camp now. Somebody has to. You go be a hero; I'll make sure the soup is hot when you're back.",
     "The camp is a village again, almost. Orphans in the hay loft, a roof on the mill. You'd hardly know it burned.",
     "Ashbrook has a bakery again! Don't tell anyone, but I stole the recipe from you. You burn everything."],
    [("tilly", "You still scare me a little. Not the glow. The way you stop talking when it happens."), ("tilly", "I don't care how strong you get. You're still the idiot who fell in the millpond."),
     ("tilly", "Promise me you'll write. Or send a rock with a note. Rocks are reliable.")], stage="ash", required=True, skin=0)
npc("haldor", "Brother Haldor", "ashbrook", "priest", "priest", 0, 1, (120, 120, 120), (230, 230, 220), (200, 190, 170), (90, 70, 50), "Fussy about protocol, secretly terrified of the day a crystal would answer.", (6, 14),
    ["Ah, {player_name}. Today is the Awakening. Stand straight, speak only when spoken to, and for the dawn's sake do not touch the crystal until I say.",
     "I conducted the ceremony. I saw the gold. I have not slept right since. Forgive me for looking at you as if you were a storm.",
     "The Church is not what I thought it was. I mean to find out what I have been serving.",
     "I rebuilt the shrine with the survivors. We left the cracked crystal in the wall. It reminds me to be brave."],
    [("haldor", "Three hundred years since the last S-rank. The records of that one are... missing. Odd, is it not?"), ("haldor", "I asked Archbishop Caldrin. He told me to stop asking."),
     ("haldor", "I stopped. That is my shame.")], stage="ash", required=True, skin=0)
npc("mira", "Little Mira", "aurelheim", "orphan", "child", 1, 2, (190, 130, 70), (210, 90, 90), (90, 70, 60), (70, 50, 40), "A small orphan who collects shiny things and unspoken promises.", (-6, 16),
    ["Are you the hero? You don't look like a hero. You look tired. Do you want my shiny rock?",
     "Tilly says you're busy saving the world. I'm busy too. I'm counting stars. There are a lot of them.",
     "You came back! Everyone says you're going to win. Did you tell the sky?",
     "I wished on a star and you won. I think I'm good at wishing."],
    [("mira", "My wishing star is called Pebble. It fell in the well. Can you find it?"), ("mira", "If you find Pebble, I'll tell you a secret. Okay? Okay."),
     ("mira", "(She whispers) The old lady at the library said a hero cried here once, a long time ago.")], stage="std", required=True, scale=0.78, home=(-8, 32))
# ---------------- Aurelheim ----------------
npc("hanna", "Guildmaster Hanna 'Iron Hanna' Ostrovsk", "aurelheim", "guildmaster", "guild", 1, 1, (150, 150, 155), (70, 80, 100), (50, 55, 70), (40, 36, 40), "Stern and unsentimental; her care shows up as extra paperwork.", (-12, 18),
    ["Sit. No, not there, that's Pip's chair. Strong heroes die alone, {player_name}. Remember that, and you may outlive your own legend.",
     "You wear S-rank like armor now. Armor has weight. Come to me when it chafes.",
     "I should have burned that Archbishop's ledgers years ago. Not your fault. Mine.",
     "The Guild has never had an S-rank retire. I'm putting in the paperwork anyway."],
    [("hanna", "I have signed fifty-three death notices for adventurers who thought they could do it alone."), ("hanna", "Half of them were better swordsmen than you."),
     ("hanna", "That is not an insult. It is a schedule. Make friends before you need them.")], required=True, skin=0, night="home", home=(-12, 31))
npc("pip", "Pip Marlowe", "aurelheim", "receptionist", "guild", 0, 0, (110, 70, 40), (190, 150, 90), (90, 70, 50), (60, 44, 36), "Talks faster than he thinks, files faster than he talks, and lost a ledger once. Once.", (-10, 21),
    ["Welcome to the Adventurer Guild! New? Rank? Name? Favorite color? Don't answer that last one, it's not on the form but I'm curious!",
     "S-rank! I asked for a bigger desk the day you got promoted. They said no. Pity.",
     "Everyone's lining up for bounties. I haven't had lunch in a week. A week! Eat something, hero.",
     "Business is booming! Heroes everywhere. Somebody please take my paperwork."],
    [("pip", "Did you know the guild board gets a new bounty every sunrise? I post them. With my own hands. Mostly."), ("pip", "My ledger is somewhere in the city. It has the only record of every rank-up. Don't tell Hanna."),
     ("pip", "Forget I said that. Please.")], required=True, skin=0, shop="guild_store")
npc("garrick", "Garrick Thorne", "aurelheim", "smith", "smith", 0, 1, (110, 60, 30), (130, 100, 70), (80, 60, 40), (50, 40, 36), "Burly and brusque; speaks to metal more gently than to customers.", (8, 27),
    ["Mind the anvil. Iron, steel, whatever you've got: I turn it into something that keeps you alive.",
     "S-rank hands deserve S-rank steel. Bring me the rare ore I asked about, would you?",
     "Brandt Cinder in Emberforge sent a letter. Says I'm slacking. I'm not. I'm resting between masterpieces.",
     "Forge is hot, ale is cold. Come by when you want that sword upgraded."],
    [("garrick", "Every sword has a temper. Mine learned from me. Yours learned from your grandfather. Treat it kindly."), ("garrick", "Your 'Dawnbrand'? Plain iron, good balance, honest blade. They don't make them that way for the show."),
     ("garrick", "Whatever fire you put in it later is your business.")], shop="garrick", required=True, skin=0)
npc("selwyn", "Madame Selwyn", "aurelheim", "alchemist", "alchemist", 1, 2, (120, 120, 140), (110, 70, 130), (70, 50, 90), (60, 40, 70), "A silver-tongued gossip who knows every secret in Aurelheim and sells most of them.", (4, 27),
    ["Darling, you look dreadful. Sit. Buy a potion. Hear a rumor. In that order, preferably.",
     "The whole city's talking about you. The tavern says you're nine feet tall. I told them you're taller.",
     "Everyone's gossip is turning grim, dear. Archbishop's been arrested. I knew it. I didn't tell you because you'd have asked how.",
     "Business is lovely. Heroes drink a lot of potions. Heroes also owe me money. Don't take it personally."],
    [("selwyn", "Moonpetal, desert bloom, frostcap, ashroot... every tonic needs a region's soul in it."), ("selwyn", "The trick is to pick the herb while it still believes it will live."),
     ("selwyn", "That is not an alchemical rule. I just say it to sound mysterious.")], shop="selwyn", required=True, skin=0)
npc("darius", "Darius Valecrest", "aurelheim", "rival", "noble", 0, 0, (30, 24, 36), (150, 40, 50), (40, 32, 44), (30, 24, 30), "Proud, sarcastic, trained since birth; beaten by a farm boy and furious about how much he respects it.", (-14, 10),
    ["Well, if it isn't the farm boy. Try not to trip over your own sword. It'd be embarrassing for both of us.",
     "I want a rematch. Not for revenge. For... accuracy. Fine. Revenge a little.",
     "I owe you. I hate saying that. Do not make me say it twice.",
     "Guildmaster's apprentice. Don't laugh. I'm very good at paperwork. It's like fencing, but nobody gets stabbed."],
    [("darius", "My father thinks a Valecrest should be first. Second place is a family scandal."), ("darius", "I train at dawn so nobody can see me bleed. You turned up at dawn once. Annoying."),
     ("darius", "Don't tell anyone, but you were the first person who beat me and didn't gloat. It's unnerving.")], required=True, skin=0, eye=(255, 140, 60), night="tavern")
npc("caldrin", "Archbishop Caldrin", "aurelheim", "churchman", "priest", 0, 0, (230, 225, 220), (245, 240, 230), (210, 190, 120), (150, 130, 90), "Warm, patient, endlessly reasonable: the kind of man who explains why the price is worth paying.", (12, 22),
    ["Child of the dawn, you honor us. The Church is always grateful for a hero who knows the value of sacrifice.",
     "So much hope rests on you. Come, let me bless the blade that bears it.",
     "(He is not here. The cathedral smells of cold candles.)",
     "(The cell door is closed. They say he still smiles.)"],
    [("caldrin", "Faith is a currency, my boy. Someone must tend the treasury."), ("caldrin", "Mirelle is our brightest light. I would never ask more of her than the dawn asks of the sun."),
     ("caldrin", "...Forgive me. I am old. My metaphors get away from me.")], required=True, skin=0, night="home", visible=["quest.MQ20 != complete"])
npc("dunmore", "Captain Rhea Dunmore", "aurelheim", "guard", "guard", 1, 1, (90, 60, 40), (90, 100, 120), (60, 70, 90), (50, 50, 60), "Disciplined and dry; commands the city watch like a woman who has seen a siege before.", (0, 38),
    ["Halt. Business in Aurelheim? State it. Briefly. I have a gate, a watch, and a headache.",
     "The city has locked down since the festival. I like it. Order suits me. You may pass, hero.",
     "Give me ten minutes with the Archbishop's guards and I'll have the cathedral sealed. You're welcome.",
     "I'll lead the army to the Hollow Gate myself. No, you can't talk me out of it. Your friends are marching too."],
    [("dunmore", "I've drilled that watch for twenty years. I know which of them will hold a line and which will faint."), ("dunmore", "The ones who faint are usually the brave ones. They try."),
     ("dunmore", "Remember that when you recruit.")], required=True, skin=0, night="tavern")
npc("voss", "Dean Alaric Voss", "spire_academy", "dean", "scholar", 0, 0, (200, 200, 210), (60, 50, 110), (40, 36, 80), (40, 36, 60), "An elegant scholar who values reputation above everything except his regret.", (0, 20),
    ["The Spire Academy does not accept visitors. Unless they bring a good reason, a better introduction, and ideally a donation.",
     "Lyra Vesperine was... a difficult student. Brilliant. I may have been wrong about her. I would say it to her face if she came back.",
     "I have reopened the east wing. It has her name on the door. Do not tell her. Let her find it.",
     "A new wing is under construction. Lyra's design. She tells me where the pillars go. I let her."],
    [("voss", "Mana is not a talent. It is a river. Teach a student to swim, not to dam."), ("voss", "I taught Lyra to dam it. I regret that."),
     ("voss", "Magic is a language of trust. I was a poor grammarian.")], required=True, skin=0, night="home")
npc("fenn", "Old Fenn", "whisperwood", "herbalist", "herbalist", 0, 3, (200, 200, 200), (90, 120, 80), (70, 90, 60), (80, 60, 40), "A hermit who talks to plants and finds people noisier.", (-4, 18),
    ["Quiet. The moss is listening. State your business, or leave it with the stones.",
     "The trees whisper your name. They whisper everyone's name, but yours louder. That's new.",
     "The corruption is receding. Roots remember the old song. I'm teaching it to the new ones.",
     "Come by whenever. Brought you a moonpetal tea. Don't say thank you. The moss gets jealous."],
    [("fenn", "Dryads don't die. They fade into the grain of the wood. Vessara faded long before she fell."), ("fenn", "I knew her. Before the corruption. She sang to the saplings."),
     ("fenn", "If you meet her, be gentle. She is a mother, not a monster.")], shop="old_fenn", required=True, skin=0)
npc("kharim", "Kharim al-Sayyid", "qasr_amun", "tribal_leader", "tribal", 0, 0, (30, 24, 20), (190, 140, 60), (150, 100, 40), (90, 60, 40), "A patient tribal elder with a laugh like a dust storm and the memory of every well in the desert.", (0, 18),
    ["Peace to you, traveler. Sit; drink. The desert teaches haste is an insult to water.",
     "The oasis tribes have agreed to guide you. Not for your sword. For the way you thanked the old woman at the well.",
     "The hourglass is silent now. The sands have started to flow forward again. We do not know whether to cheer or weep.",
     "You will always have a tent among us. And a camel. A very bad-tempered camel."],
    [("kharim", "In my grandfather's time, the desert sang. Then a king-in-the-sands stole the song and hid it in glass."), ("kharim", "Khemet-Ur. They say he can unmake a minute."),
     ("kharim", "Be careful with your mistakes there. He keeps them.")], required=True, skin=1)
npc("zaira", "Zaira", "qasr_amun", "merchant", "merchant", 1, 2, (50, 30, 20), (170, 60, 90), (100, 40, 60), (80, 50, 40), "A caravan merchant who treats every price as an opening line.", (-6, 24),
    ["Traveler! You look like someone who needs spice. Everyone needs spice. Look, taste, argue, then buy.",
     "The Hero of the Sands! I put your name on a bag of cumin. Triple the price. Don't be offended; it moves.",
     "The caravan roads are open again. More customers, more bandits, more fun.",
     "You're family, so for you the price is only double."],
    [("zaira", "Rare spices are like rumors: the best ones are older than the people telling them."), ("zaira", "I'm looking for a blend my grandmother made. The recipe is hidden in a mural in the Khemet ruins."),
     ("zaira", "Find it for me and I'll cook you a feast that ends wars.")], shop="zaira", required=True, skin=1)
npc("anwen", "Anwen the Archivist", "khemet_ruins", "scholar", "scholar", 1, 2, (200, 160, 100), (150, 100, 60), (110, 80, 50), (80, 60, 40), "A scholar who talks about the dead as if they were late for dinner.", (0, 14),
    ["Careful where you step. This floor is four thousand years older than your family. Ask before you sneeze.",
     "The murals show a lone hero standing at the center of every scene. The artists were paid to flatter or to warn. I haven't decided.",
     "Khemet-Ur is gone. The hourglass counts honestly again. I can finally date my own handwriting.",
     "I'm cataloguing everything. Even the footprints. Especially yours."],
    [("anwen", "Look at this mural. A man in light, alone, facing a crowd of faceless shadows."), ("anwen", "Every kingdom has a story where one person bears the burden. Almost none of them say what happened afterward."),
     ("anwen", "Afterward is where the truth lives.")], required=True, skin=0)
npc("torvik", "Skald Torvik", "hrimvald", "guide", "guide", 0, 0, (200, 200, 205), (100, 130, 160), (70, 90, 120), (50, 60, 80), "A mountain guide who sings to stay warm and lies about the weather.", (-4, 20),
    ["Welcome to Hrimvald! The weather is lovely. By which I mean the wind only wants to kill you a little.",
     "Whiteout Pass is no joke. I know a route. It's slower. It is also not death.",
     "The Choir's silence ended. For a night the whole mountain sang. I wept like a baby. It was in tune.",
     "I'll take you up any peak you like. As long as it's not the one with the frozen lighthouse."],
    [("torvik", "My daughter was a climber. She went up the Lighthouse and the mountain kept her."), ("torvik", "I don't blame the mountain. I blame myself for teaching her to love it."),
     ("torvik", "Whatever you do, don't fall in love with something you can't carry back down.")], shop="hrimvald", required=True, skin=0)
npc("elowen", "Sister Elowen", "hrimvald", "caretaker", "priest", 1, 2, (190, 190, 200), (200, 210, 235), (150, 170, 210), (110, 120, 150), "A cathedral caretaker who speaks in whispers and listens in full sentences.", (6, 16),
    ["Please lower your voice. The Choir Cathedral listens to everything, and it holds grudges.",
     "Isrevna's songs mention the first light. I was told it was a hymn. I think it was a name.",
     "She is silent now. For the first time in three hundred years. I sat in the nave and listened to my own heartbeat.",
     "I light a candle every morning for her. It seems the least I can do."],
    [("elowen", "She was our choir mistress once. A singer so good the ice kept her voice."), ("elowen", "When the demons came, she sang to keep them out. It worked. It kept everyone else out too."),
     ("elowen", "Be gentle. She isn't evil. She's lonely.")], required=True, skin=0)
npc("brandt", "Forgemaster Brandt Cinder", "emberforge", "forgemaster", "smith", 0, 1, (60, 50, 40), (110, 70, 50), (80, 50, 40), (40, 30, 24), "The loudest man in Cinderhold, and the most careful with a hammer.", (8, 26),
    ["You have good bones for a blade! Bring me the best ore in the mines and I'll make you weapons the old kings would weep over.",
     "I'll forge the party's final weapons. All four. You'll have to hold off the volcano for a week. Think you can manage?",
     "The forge hums again. The Singing Anvil! I can hear it at night. Like the hymns of my grandfather.",
     "My apprentices will make a thousand blades. The war ended; the building didn't."],
    [("brandt", "There's a forge-song about a tired knight, you know. Old as the mountain. Nobody knows the last verse."), ("brandt", "My grandfather always said the knight forged a sword that never needed sharpening. Because he never put it down."),
     ("brandt", "Sad song. Good rhythm for hammering.")], shop="brandt", required=True, skin=0)
npc("ysolde", "Ysolde Ashfall", "emberforge", "guildleader", "miner", 1, 1, (160, 160, 165), (110, 100, 100), (80, 70, 70), (60, 50, 50), "Leads the miners' guild with soot on her cheek and steel in her spine.", (-10, 20),
    ["Fifteen-hour shifts, rockfall every week, pay that insults a mule. That's why I'm in charge. Somebody has to shout.",
     "The mines are rumbling. The eruption's near. I won't send my people down until it's safe. Don't try to argue.",
     "The strike ended. We got what we asked for. Not all of it. But enough to start asking again.",
     "My people are heroes too. Mark that in your journal."],
    [("ysolde", "A miner knows the dark. We carry our own lamps and our own courage."), ("ysolde", "Your type goes into the dark and comes out a legend. We go in and come out with ore."),
     ("ysolde", "Both are work. Never forget that.")], required=True, skin=0)
npc("nox", "Nox", "front_camp", "informant", "broker", 0, 3, (0, 0, 0), (50, 40, 70), (30, 24, 44), (20, 14, 30), "A former cultist who sells information and keeps a ledger of his own sins.", (-8, 18),
    ["Information has a price. So does silence. I sell both. Today, I'm feeling generous. Ask.",
     "The cult is hollow, in the literal sense. The Hollow King's heart is a rumor. Pay up and I'll tell you what I know.",
     "I heard what happened at the throne. I'm not a believer in much. I almost believe in you.",
     "I burned my ledger. All of it. I'm told this makes me a good man. I'm told I should keep a spare."],
    [("nox", "I was a believer once. They told me the world was suffering and we alone could end it."), ("nox", "I left when I realized they had no plan for what comes after."),
     ("nox", "A cause that has no afterwards isn't mercy. It's an ending in a nice coat.")], required=True, skin=0, eye=(190, 120, 255))
npc("edda", "Mayor Edda", "qasr_amun", "mayor", "noble", 1, 1, (170, 170, 175), (120, 90, 50), (90, 60, 40), (70, 50, 40), "A formidable politician who treats every petitioner as a negotiating partner.", (0, 22),
    ["The oasis feeds six tribes and one guild. Every sip is a political act. Do try to remember that when you ask for water.",
     "I've balanced the trade council for thirty years. Your arrival is the most disruptive thing since the drought. Welcome.",
     "The council thanks you. In writing. In triplicate. With a small gift. That's how thanks work here.",
     "Qasr Amun is yours for life. Not as a gift. As a lease."],
    [("edda", "Politics is just friendship with budgets."), ("edda", "I've seen three assassins, two plagues, and a wedding that lasted a month. The wedding was worse."),
     ("edda", "If you ever need a favor from the council, ask me before you ask the tribes. They like to bargain.")], required=True, skin=1, night="home")
npc("marek", "Captain Marek", "hrimvald", "guard", "guard", 0, 1, (120, 100, 90), (90, 110, 140), (60, 80, 110), (50, 60, 80), "A mountain patrol captain who counts his people every sunrise and every sunset.", (-6, 12),
    ["Patrol is out. Avalanche warning. Stay inside unless you have a very good reason and a very good coat.",
     "We lost a team in the pass last week. If you find them, bring them home. Even if there's only a hat.",
     "The Choir quieted. The wolves quieted. The mountain quiet is the loudest thing I've heard.",
     "I counted everyone this morning. All present. First time in two years."],
    [("marek", "Avalanches announce themselves with a small sound, like someone clearing their throat."), ("marek", "If you hear it, run uphill. Counterintuitive. Lifesaving."),
     ("marek", "Ask me how I know.")], required=True, skin=0, night="tavern")
npc("lio", "Lio the Wandering Bard", "roaming", "bard", "bard", 0, 2, (150, 90, 40), (180, 90, 60), (110, 60, 50), (80, 50, 40), "A traveling bard who never stays, always knows the lyric, and remembers your last verse.", (6, 20),
    ["Ho, traveler! A song for a coin, a story for a seat by the fire. Which will it be?",
     "I wrote a ballad about you. It has a rhyme for 'Ascendant.' I'm very proud. It doesn't rhyme.",
     "They're singing it in every tavern. Nobody gets the words right. I gave up correcting them.",
     "A new verse: and in the end he was not alone. I'm told it doesn't scan. I'm keeping it."],
    [("lio", "Every town has a song, and every song has a verse nobody sings."), ("lio", "In Cinderhold they hum one about a knight who never put down his sword."),
     ("lio", "In Frostspire, a choir about 'the first light.' Both end the same way, mid-sentence. Funny. Almost like someone ran out of breath.")], required=True, skin=0, night="tavern")
# ---------------- recruitable companions as NPCs (before they join) ----------------
npc("bram", "Sir Bram Ironvale", "fort_greywall", "knight", "knight", 0, 1, (92, 78, 70), (120, 134, 160), (58, 62, 80), (40, 36, 44), "A guilt-ridden former captain who drinks to quiet a roll call only he can hear.", (0, 16),
    ["Go away, kid. I'm not for hire. I'm not for anything. I'm for sitting here with a bottle and a bad memory.",
     "You again. Fine. You've got a stubborn jaw. Stubborn, I respect.",
     "Behind me, kid. I'll hold the line. That's the one thing I do right.",
     "Greywall's names are on the wall. I read them out every morning. It helps."],
    [("bram", "I ordered the retreat at Greywall. Saved ten thousand. Left forty behind."), ("bram", "They tell me that's a good trade. They don't hear the forty."),
     ("bram", "You want me to lift a shield again? Give me a reason I can carry.")], required=True, skin=0, visible=["flag.bram_joined == 0"], eye=(130, 190, 240))
npc("lyra", "Lyra Vesperine", "forbidden_library", "mage", "mage", 1, 0, (206, 212, 240), (72, 52, 140), (40, 30, 80), (30, 24, 52), "A prodigy whose power outruns her patience; hiding because she believes she is a danger to everyone.", (0, 14),
    ["Don't come closer. I mean it. The shelves are rattling, and I'm not the one doing it. Okay, I am. Go away.",
     "You're the one with more raw power than me. Everyone says so. I'd like to see it. Don't hold back, or I'll be insulted.",
     "My mana feels... quieter. Like someone is holding the other end of the rope.",
     "I'm building an academy wing. With my name on it. Don't tell Voss it was my idea. He likes to think he thought of it."],
    [("lyra", "I destroyed a wing of the Academy when I was fifteen. Seven injured. No one died. That's not the point."), ("lyra", "The point is I couldn't stop it. I tried. It just kept coming."),
     ("lyra", "If you're stronger than me, you've felt that. Haven't you?")], required=True, skin=0, visible=["flag.lyra_joined == 0"], eye=(120, 230, 255))
npc("mirelle", "Sister Mirelle Dawnsong", "sanctum_of_dawn", "priestess", "priest", 1, 2, (236, 178, 168), (242, 238, 232), (236, 232, 224), (150, 110, 80), "A radiant priestess whose smile never quite reaches the cost she pays for it.", (0, 14),
    ["Blessings of the dawn, traveler. Are you hurt? Please, sit. It's no trouble. It's never trouble.",
     "You noticed I'm tired. Most people don't. It's fine. The light provides.",
     "I'm learning a new kind of healing. One that doesn't take from me. Light will find a way.",
     "I took a day off. A whole day. I saw a market. I ate three pastries. I want to do it again."],
    [("mirelle", "I was five when the Church found me. They said I had a gift. I believed them."), ("mirelle", "I've healed hundreds. I don't mind giving. I mind that no one told me how much."),
     ("mirelle", "...Please don't tell the others I said that.")], required=True, skin=0, visible=["flag.mirelle_joined == 0"], eye=(150, 235, 190))
